-- 1. Run a transfer inside a transaction
BEGIN;
  UPDATE accounts SET balance = balance - 100 WHERE id = 1;
  UPDATE accounts SET balance = balance + 100 WHERE id = 2;
  -- If any error occurs, ROLLBACK is called; else COMMIT
COMMIT;

-- 2. Create a B-tree index on a high-cardinality column
CREATE INDEX idx_orders_user_id ON orders (user_id);

-- 3. Inspect the query plan (PostgreSQL)
EXPLAIN ANALYZE
  SELECT * FROM orders WHERE user_id = 42;
-- Look for: "Index Scan using idx_orders_user_id" — that's fast.
-- "Seq Scan" means the planner ignored the index (low cardinality
-- or table too small); add ANALYZE to refresh statistics.
